#import <UIKit/UIKit.h>
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>

#include <SDL3/SDL.h>
#include <SDL3/SDL_main.h>

#include <cerrno>
#include <cstdio>
#include <string>
#include <vector>

#include "frontend.h"
